<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';send_cors_headers();$code=trim((string)($_GET['code']??''));$stmt=get_db()->prepare('SELECT l.*,c.attribution_days,c.status AS campaign_status,c.starts_at,c.ends_at,i.status AS influencer_status FROM influencer_referral_links l JOIN influencer_campaigns c ON c.id=l.campaign_id JOIN influencers i ON i.id=l.influencer_id WHERE l.code=:code AND l.status="active"');$stmt->execute(['code'=>$code]);$link=$stmt->fetch();if(!$link||$link['campaign_status']!=='active'||$link['influencer_status']!=='active'||strtotime($link['starts_at'])>time()||strtotime($link['ends_at'])<time())json_response(404,['success'=>false,'message'=>'Referral link is unavailable.']);$visitor=(string)($_COOKIE['ci_referral_visitor']??'');if(!preg_match('/^[a-f0-9]{64}$/',$visitor)){$visitor=bin2hex(random_bytes(32));setcookie('ci_referral_visitor',$visitor,['expires'=>time()+86400*(int)$link['attribution_days'],'path'=>'/','secure'=>secure_cookie(),'httponly'=>true,'samesite'=>'Lax']);}$clickId=uuid_string();$ipHash=request_fingerprint(request_ip());$fraud=[];if(rate_limit('referral-click|'.$ipHash.'|'.$link['id'],30,3600))$fraud[]='high_click_velocity';get_db()->prepare('INSERT INTO referral_clicks (id,referral_link_id,visitor_hash,ip_hash,user_agent_hash,fraud_flags_json,clicked_at) VALUES (:id,:link,:visitor,:ip,:agent,:fraud,UTC_TIMESTAMP())')->execute(['id'=>$clickId,'link'=>$link['id'],'visitor'=>hash_hmac('sha256',$visitor,APP_KEY),'ip'=>$ipHash,'agent'=>request_fingerprint((string)($_SERVER['HTTP_USER_AGENT']??'')),'fraud'=>$fraud?json_encode($fraud):null]);setcookie('ci_referral_click',$clickId,['expires'=>time()+86400*(int)$link['attribution_days'],'path'=>'/','secure'=>secure_cookie(),'httponly'=>true,'samesite'=>'Lax']);json_response(200,['success'=>true,'destination_url'=>$link['destination_url']]);
